<?php
namespace App\Http\Controllers;use App\Models\{Department,Media,Event,Achievement,Collective};
class ChoreographyController extends Controller{public function __invoke(){ $department=Department::where(fn($q)=>$q->where('name','like','%хореограф%')->orWhere('slug','like','%choreograph%'))->where('is_active',true)->with(['teachers','programs'])->first();$videos=Media::where('collection','choreography')->whereNotNull('external_url')->latest()->get();$events=Event::published()->where(fn($q)=>$q->where('event_type','choreography')->orWhere('title','like','%танц%')->orWhere('title','like','%хореограф%')->orWhere('description','like','%хореограф%'))->with(['performances'])->latest('starts_at')->limit(8)->get();$concerts=$events->filter(fn($e)=>$e->starts_at->isPast()&&$e->has_concert_recording)->take(4);$achievements=Achievement::where('is_published',true)->where(fn($q)=>$q->where('title','like','%танц%')->orWhere('title','like','%хореограф%')->orWhere('description','like','%хореограф%'))->latest('event_date')->limit(8)->get();$collectives=Collective::where('is_active',true)->where(fn($q)=>$q->where('name','like','%танц%')->orWhere('description','like','%хореограф%'))->orderBy('sort')->get();return view('choreography.index',compact('department','videos','events','concerts','achievements','collectives'));}}